-- 005: Outbox lease fencing (T-009).
-- Additive only: one nullable column, one function, one trigger. No existing
-- row is rewritten and no column, table or index is dropped.

-- Each claim stores an unguessable 128-bit token (32 lowercase hex chars),
-- generated by the worker, on every row it locks. Completion, retry and
-- release update a row only WHERE id = $id AND claim_token = $token, so a worker
-- whose lease expired and was reclaimed cannot complete, clear or reschedule a
-- row owned by the newer claim. Rows that are unclaimed, published, or locked
-- by a pre-005 worker carry NULL.
ALTER TABLE consent_outbox_events
  ADD COLUMN IF NOT EXISTS claim_token text;

-- Rolling-update fence for pre-005 workers. Old workers neither write nor
-- check claim_token, so without this trigger they could complete or
-- reschedule a row a new worker has claimed, and an old re-claim of an expired
-- row would leave the previous owner's token valid. While a row holds a token:
--   * an old-style re-claim (sets a new locked_at, leaves claim_token alone)
--     revokes the token, so the previous owner is fenced; and
--   * any other old-style change to the lease/publication columns (complete,
--     reschedule, clear) is rejected with SQLSTATE 55000.
-- Token-aware statements always change claim_token (new token on claim, NULL
-- on complete/retry/release) and are unaffected. The trigger can be dropped by
-- a later migration once no pre-005 worker image can run.
CREATE OR REPLACE FUNCTION consent_outbox_fence_untokened_writes() RETURNS trigger AS $$
BEGIN
  IF OLD.claim_token IS NOT NULL AND NEW.claim_token IS NOT DISTINCT FROM OLD.claim_token THEN
    IF NEW.published_at IS NULL AND NEW.locked_at IS NOT NULL
       AND NEW.locked_at IS DISTINCT FROM OLD.locked_at THEN
      NEW.claim_token := NULL;
    ELSIF NEW.published_at IS DISTINCT FROM OLD.published_at
       OR NEW.locked_at IS DISTINCT FROM OLD.locked_at
       OR NEW.locked_by IS DISTINCT FROM OLD.locked_by
       OR NEW.next_attempt_at IS DISTINCT FROM OLD.next_attempt_at THEN
      RAISE EXCEPTION 'consent_outbox_events row % is owned by a fenced claim', OLD.id
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS consent_outbox_fence_untokened ON consent_outbox_events;
CREATE TRIGGER consent_outbox_fence_untokened
  BEFORE UPDATE ON consent_outbox_events
  FOR EACH ROW EXECUTE FUNCTION consent_outbox_fence_untokened_writes();

-- Existing-data validation (read-only; run before and after deploy):
--
--   Rows locked by a pre-005 worker have no token. A new worker can claim
--   them only after the 2-minute lease expires, exactly as before:
--     SELECT count(*) FROM consent_outbox_events
--      WHERE published_at IS NULL AND locked_at IS NOT NULL AND claim_token IS NULL;
--
--   Published rows must never hold a token:
--     SELECT count(*) FROM consent_outbox_events
--      WHERE published_at IS NOT NULL AND claim_token IS NOT NULL;   -- expect 0
